    }

  return (
    <Container className="min-vh-100 d-flex flex-sm-column mt-3">
      {order.allOrders.map(oneOrder =>
        <Container key={oneOrder.id}>
          <h4><b>Замовлення №{oneOrder.id}</b></h4>
          <Button onClick={() => setOrderVisible(true)}>Переглянути</Button>
          <OrderInfo show={orderVisible} onHide={() => setOrderVisible(false)}/>

          <hr/>
        </Container>
      )}
    </Container>
  );
});

export default Orders;
